-- DEN-126: consentimiento operativo del conector remoto Claude, aislado por usuario/tenant.
create table if not exists cashflow.denarius_mcp_oauth_grant(owner_id uuid primary key references auth.users(id)on delete cascade,tenant_id uuid not null references cashflow.tenant(id)on delete cascade,scopes text[]not null,updated_at timestamptz not null default now());alter table cashflow.denarius_mcp_oauth_grant enable row level security;revoke all on cashflow.denarius_mcp_oauth_grant from public,anon,authenticated;grant all on cashflow.denarius_mcp_oauth_grant to service_role;
alter table cashflow.denarius_mcp_oauth_grant add constraint denarius_mcp_oauth_grant_scopes check(cardinality(scopes)>=1 and scopes<@array['financial:read','alerts:read','actions:write']::text[]and'financial:read'=any(scopes));
create or replace function cashflow.set_denarius_mcp_oauth_grant(p_tenant_id uuid,p_scopes text[])returns jsonb language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_scopes text[];begin if not exists(select 1 from cashflow.tenant where id=p_tenant_id and owner_id=auth.uid())then raise exception'TENANT_NOT_FOUND';end if;select array_agg(distinct s order by s)into v_scopes from unnest(coalesce(p_scopes,'{}'))s;if v_scopes is null or not('financial:read'=any(v_scopes))or not(v_scopes<@array['financial:read','alerts:read','actions:write']::text[])then raise exception'INVALID_SCOPES';end if;insert into cashflow.denarius_mcp_oauth_grant(owner_id,tenant_id,scopes)values(auth.uid(),p_tenant_id,v_scopes)on conflict(owner_id)do update set tenant_id=excluded.tenant_id,scopes=excluded.scopes,updated_at=now();return jsonb_build_object('tenant_id',p_tenant_id,'scopes',v_scopes);end$$;
create or replace function cashflow.get_denarius_mcp_oauth_grant(p_tenant_id uuid)returns jsonb language sql stable security definer set search_path=cashflow,public,pg_temp as $$select coalesce((select jsonb_build_object('tenant_id',tenant_id,'scopes',scopes,'updated_at',updated_at)from cashflow.denarius_mcp_oauth_grant where owner_id=auth.uid()and tenant_id=p_tenant_id),jsonb_build_object('tenant_id',p_tenant_id,'scopes',array['financial:read']::text[]))$$;
create or replace function cashflow.resolve_denarius_mcp_oauth_grant(p_owner_id uuid)returns table(tenant_id uuid,owner_id uuid,scopes text[])language plpgsql security definer set search_path=cashflow,public,pg_temp as $$begin if auth.role()<>'service_role'then raise exception'FORBIDDEN';end if;return query select g.tenant_id,g.owner_id,g.scopes from cashflow.denarius_mcp_oauth_grant g join cashflow.tenant t on t.id=g.tenant_id and t.owner_id=g.owner_id where g.owner_id=p_owner_id;end$$;
revoke all on function cashflow.set_denarius_mcp_oauth_grant(uuid,text[]),cashflow.get_denarius_mcp_oauth_grant(uuid)from public,anon;grant execute on function cashflow.set_denarius_mcp_oauth_grant(uuid,text[]),cashflow.get_denarius_mcp_oauth_grant(uuid)to authenticated;revoke all on function cashflow.resolve_denarius_mcp_oauth_grant(uuid)from public,anon,authenticated;grant execute on function cashflow.resolve_denarius_mcp_oauth_grant(uuid)to service_role;
